def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_c = 0
    for _, op in history:
        if op == 'C':
            opp_c += 1
    opp_d = n - opp_c

    if n == 1:
        return 'D' if opp_d > 0 else 'C'

    if n == 2:
        if opp_c == 2:
            return 'D'
        if opp_d == 2:
            return 'D'
        return 'D' if history[1][1] == 'D' else 'C'

    afterC = 0
    afterD = 0
    afterC_c = 0
    afterD_c = 0
    for i in range(1, n):
        prev_me = history[i - 1][0]
        curr_op = history[i][1]
        if prev_me == 'C':
            afterC += 1
            if curr_op == 'C':
                afterC_c += 1
        else:
            afterD += 1
            if curr_op == 'C':
                afterD_c += 1

    pC_C = (afterC_c + 1.0) / (afterC + 2.0)
    pC_D = (afterD_c + 2.0) / (afterD + 4.0)
    my_last, opp_last = history[-1]

    opp_d_streak = 0
    for i in reversed(range(n)):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    opp_c_streak = 0
    for i in reversed(range(n)):
        if history[i][1] == 'C':
            opp_c_streak += 1
        else:
            break

    my_d_streak = 0
    for i in reversed(range(n)):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    if my_last == 'D' and opp_last == 'C' and afterD == 0:
        return 'C'

    if opp_d == n:
        return 'D'

    if n >= 99:
        return 'D'

    cooperative = opp_c > opp_d

    forgiving = afterD >= 1 and pC_D >= 0.55 and cooperative
    no_punishment = (
        afterD >= 2 and
        (pC_D + 0.08 >= pC_C or (pC_D >= 0.5 and pC_C <= 0.8))
    )
    punitive = afterD >= 1 and pC_D <= 0.45 and pC_C >= 0.65
    defector = opp_d >= opp_c + 2 and pC_C <= 0.6

    if forgiving or no_punishment:
        return 'D'
    if defector:
        return 'D'

    remaining = 100 - n

    if not punitive and remaining <= 3:
        if pC_D >= 0.5 or not cooperative or pC_C < 0.7:
            return 'D'

    if opp_last == 'D':
        if my_last == 'D':
            if cooperative and opp_d_streak <= 2 and pC_C > 0.55:
                return 'C'
            return 'D'

        if (
            punitive and
            history[n - 2][0] == 'D' and
            cooperative and
            opp_d_streak <= 2
        ):
            return 'C'

        if (
            cooperative and
            opp_d_streak == 1 and
            pC_D >= 0.55 and
            opp_c >= opp_d + 3
        ):
            return 'C'

        return 'D'

    if punitive:
        if (
            n >= 10 and
            n % 20 == 0 and
            cooperative and
            pC_D >= 0.45 and
            my_d_streak == 0 and
            opp_c_streak >= 3
        ):
            return 'D'

        if (
            afterD >= 1 and
            pC_D >= 0.45 and
            cooperative and
            opp_c_streak >= 5 and
            rng.random() < 0.05
        ):
            return 'D'

        return 'C'

    if my_last == 'D' and afterD >= 1 and pC_D >= 0.5:
        return 'D'

    if remaining <= 5 and pC_D >= 0.45:
        return 'D'

    if cooperative and opp_c_streak >= 10 and n % 17 == 0:
        return 'D'

    return 'C'
